<script setup lang="ts">
import {ref,watch} from 'vue'
import ListingEditorRead from './ListingEditorRead.vue'
import type {SubmitPreview,Submission} from './listingTypes'
const props=defineProps<{preview:SubmitPreview|null,listingId:number,checking?:boolean,validationError?:string}>(),emit=defineEmits<{close:[],submitted:[value:Submission],busy:[value:boolean]}>()
const sending=ref(false),error=ref(''),result=ref<Submission|null>(null)
watch(()=>props.preview,()=>{error.value='';result.value=null})
async function action(verify=false){if(props.checking||props.validationError||!props.preview?.preview_id)return;sending.value=true;emit('busy',true);error.value='';try{const path=verify?`submissions/${result.value!.id}/verify`:'submit';const r=await fetch(`/api/listings/${props.listingId}/${path}`,{method:'POST',headers:{'Content-Type':'application/json','X-ERP-Client':'web'},body:JSON.stringify(verify?{}:{preview_id:props.preview.preview_id,confirmed:true})});const d=await r.json();if(!r.ok)throw new Error(typeof d.detail==='string'?d.detail:'提交失败');result.value=d;emit('submitted',d)}catch(e){error.value=(e as Error).message}finally{sending.value=false;emit('busy',false)}}
</script>
<template><el-dialog :model-value="!!preview" title="提交预览" width="min(1080px,94vw)" :close-on-click-modal="false" :close-on-press-escape="!sending" :show-close="!sending" @close="emit('close')"><template v-if="preview"><p class="preview-identity">{{preview.store}} · {{preview.marketplace}} · {{preview.sku}}</p><p class="muted">仅提交以下 {{preview.diff.length}} 项修改。请核对修改前后的内容，再点击确认提交。</p><el-alert v-if="checking" title="修改对比已就绪，正在核对亚马逊最新信息并校验；通过后可确认提交。" type="info" :closable="false" show-icon/><el-alert v-if="validationError" :title="validationError" type="error" :closable="false"/><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-alert v-if="result" :title="result.message||result.status" :type="result.status==='verified'?'success':result.status==='rejected'?'error':'warning'" :closable="false"/><div v-for="warning in preview.warnings" :key="warning" class="preview-warning">{{warning}}</div><div v-for="(issue,i) in preview.issues" :key="i" class="preview-issue" :class="{blocking:issue.severity==='ERROR'}">{{issue.code}} · {{issue.message}}</div><div class="preview-changes"><section v-for="change in preview.diff" :key="change.key"><h3>{{change.label}}<span v-if="preview.counts[change.key]">{{preview.counts[change.key].characters.join(' / ')}} 字符</span></h3><div class="preview-columns"><div><h4>{{checking||validationError?'修改前（本地快照）':'修改前（已核对亚马逊）'}}</h4><ListingEditorRead :value="change.before" :schema="change.schema"/></div><div><h4>修改后</h4><ListingEditorRead :value="change.after" :schema="change.schema"/></div></div></section></div><div v-for="(issue,i) in result?.response?.issues||[]" :key="i" class="preview-issue">{{issue.code}} · {{issue.message}}</div><p v-if="!preview.can_submit&&!checking&&!validationError" class="preview-warning">预校验未通过，请根据问题说明返回编辑。</p></template><template #footer><el-button :disabled="sending" @click="emit('close')">{{result?'关闭':'返回编辑'}}</el-button><el-button v-if="result&&['accepted','unknown','submitting'].includes(result.status)" :loading="sending" @click="action(true)">核对结果</el-button><el-button v-if="!result" type="primary" :loading="sending" :disabled="checking||!!validationError||!preview?.can_submit" @click="action()">{{checking?'正在校验…':'确认提交'}}</el-button></template></el-dialog></template>
<style scoped>.preview-identity{font-weight:600;color:#2b684e}.preview-changes{max-height:56vh;overflow:auto}.preview-changes section{border:1px solid #e2eae5;border-radius:8px;margin:14px 0;overflow:hidden}.preview-changes h3{font-size:13px;background:#f4f8f5;margin:0;padding:12px 16px;display:flex;justify-content:space-between}.preview-changes h3 span{font-weight:400;font-size:11px;color:#82968a}.preview-columns{display:grid;grid-template-columns:1fr 1fr;gap:24px;padding:14px 16px;font-size:12px;line-height:1.8}.preview-columns>div{min-width:0}.preview-columns h4{font-size:11px;color:#84998b;margin:0 0 8px}.preview-warning,.preview-issue{font-size:12px;line-height:1.8;color:#997442;margin:8px 0}.blocking{color:#b64b3b}@media(max-width:650px){.preview-columns{grid-template-columns:1fr}}</style>
